#include <iostream>
#include <iterator>
#include <string>
#include <vector>
#include "../firmware/bytereel_2026/web_json.h"
#include "../firmware/bytereel_2026/source_validation.h"
#include "../firmware/bytereel_2026/slot_upload_validation.h"
#include "../firmware/bytereel_2026/panel_display.h"

static bool hexBank(const std::string&s,uint8_t out[256]){if(s.size()!=512)return false;auto h=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='A'&&c<='F')return c-'A'+10;if(c>='a'&&c<='f')return c-'a'+10;return -1;};for(unsigned i=0;i<256;i++){int a=h(s[i*2]),b=h(s[i*2+1]);if(a<0||b<0)return false;out[i]=(uint8_t)((a<<4)|b);}return true;}
int main(int argc,char**argv){std::string input((std::istreambuf_iterator<char>(std::cin)),{});if(argc<2)return 2;try{
  if(std::string(argv[1])=="assemble"){std::string bank,source;bool n=false;if(!br_json_string(input,"bank",bank,n)||n||!br_json_string(input,"source",source,n)||n)return 2;BrAsmResult a=br_assemble(source,bank.c_str());static const char*d="0123456789ABCDEF";std::string hex;hex.reserve(512);for(uint8_t b:a.bytes){hex+=d[b>>4];hex+=d[b&15];}std::cout<<"{\"bank\":\""<<bank<<"\",\"hex\":\""<<hex<<"\",\"bytes\":"<<a.written<<"}";return 0;}
  if(std::string(argv[1])=="validate"){if(argc!=3)return 2;if(input.size()>16384||!br_json_balanced(input)){std::cout<<"{\"ok\":false,\"field\":\"body\",\"reason\":\"invalid or oversized request JSON\"}";return 0;}uint32_t expectedRevision=0;if(!br_json_unsigned(input,"expectedRevision",expectedRevision)){std::cout<<"{\"ok\":false,\"field\":\"expectedRevision\",\"reason\":\"integer revision required\"}";return 0;}size_t start=0,end=0;if(!br_json_object_range(input,"slot",start,end)){std::cout<<"{\"ok\":false,\"field\":\"slot\",\"reason\":\"slot object required\"}";return 0;}uint8_t route=(uint8_t)std::stoi(argv[2]);BrSlotUploadValidation v=br_validate_slot_upload(input.substr(start,end-start),route);if(!v.ok){std::cout<<"{\"ok\":false,\"field\":\""<<v.field<<"\",\"reason\":\""<<v.reason<<"\"}";return 0;}std::cout<<"{\"ok\":true,\"route\":"<<(unsigned)route<<",\"expectedRevision\":"<<expectedRevision<<"}";return 0;}
  if(std::string(argv[1])=="panel-load"){size_t start=0,end=0;if(!br_json_object_range(input,"slot",start,end))return 3;std::string record=input.substr(start,end-start);uint8_t v[256],a[256],vr[256],ar[256];for(const auto&p:{std::pair<const char*,uint8_t*>{"video",v},{"audio",a}}){size_t bs=0,be=0;std::string obj,hex;bool nul=false;if(!br_json_object_range(record,p.first,bs,be)||!br_json_string(record.substr(bs,be-bs),"hex",hex,nul)||nul||!hexBank(hex,p.second))return 6;}if(!br_publish_banks(true,v,a,vr,ar))return 7;std::cout<<"{\"ok\":true,\"videoFirst\":"<<(unsigned)vr[0]<<",\"audioFirst\":"<<(unsigned)ar[0]<<"}";return 0;}
  if(std::string(argv[1])!="validate"||argc!=3)return 2;int route=std::stoi(argv[2]);size_t start=0,end=0;uint32_t slot=99;if(!br_json_object_range(input,"slot",start,end))return 3;std::string record=input.substr(start,end-start);if(!br_json_unsigned(record,"slot",slot)||slot!=(uint32_t)route)return 4;
  for(const char*name:{"video","audio"}){size_t bs=0,be=0;if(!br_json_object_range(record,name,bs,be))return 5;std::string obj=record.substr(bs,be-bs),hex,source;bool isNull=false,matches=false;uint8_t bytes[256];if(!br_json_string(obj,"hex",hex,isNull)||isNull||!hexBank(hex,bytes)||!br_json_string(obj,"source",source,isNull))return 6;bool hasMatch=br_json_boolean(obj,"sourceMatches",matches);if(!hasMatch)matches=!isNull;if(isNull)matches=false;if(matches){BrSourceCheckResult c=br_check_source_bytes(source,strcmp(name,"video")==0?"VIDEO":"AUDIO",bytes);if(c.result!=BR_SOURCE_MATCH){std::cout<<"{\"ok\":false,\"field\":\""<<name<<".source\",\"slot\":"<<slot+1<<",\"address\":"<<c.address<<",\"expected\":"<<(unsigned)c.expected<<",\"supplied\":"<<(unsigned)c.supplied<<"}";return 0;}}}
  std::cout<<"{\"ok\":true,\"route\":"<<route<<",\"slot\":"<<slot<<"}";return 0;
 }catch(const std::exception&e){std::cout<<"{\"ok\":false,\"error\":\""<<e.what()<<"\"}";return 0;}}
